layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(248, 158, 157); border-left: 10px solid rgb(212, 111, 147); border-radius: 0px; font-family: Inter; font-size: 16px; font-weight: 600; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 16px; padding-bottom: 16px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-size 0.3s }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: Inter; font-size: 40px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: Inter; font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-size 0.3s }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: Inter; font-size: 16px; font-weight: 600; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: background-size 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: Inter; font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-size 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: Inter; font-size: 16px; font-weight: 600; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-size 0.3s }
[data-ryt="rec-card"] [data-ryt="title"]:hover { opacity: 1; opacity: 1 }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { opacity: 1; opacity: 1 }
[data-ryt="nav"] a:hover { opacity: 1; opacity: 1 }
[data-ryt="brand"]:hover { opacity: 1 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { opacity: 1 }
